#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int read_line(char *buffer, size_t capacity)
{
    int ch;

    if (fgets(buffer, (int)capacity, stdin) == NULL) {
        return 0;
    }
    if (strchr(buffer, '\n') != NULL) {
        return 1;
    }

    ch = fgetc(stdin);
    if (ch == EOF) {
        return ferror(stdin) == 0;
    }
    if (ch == '\n') {
        return 1;
    }
    do {
        ch = fgetc(stdin);
    } while (ch != '\n' && ch != EOF);
    return 0;
}

static int parse_int_line(const char *line, int *out)
{
    char *end;
    long value;

    errno = 0;
    value = strtol(line, &end, 10);
    if (line == end || errno == ERANGE || value < INT_MIN || value > INT_MAX) {
        return 0;
    }
    while (isspace((unsigned char)*end) != 0) {
        ++end;
    }
    if (*end != '\0') {
        return 0;
    }
    *out = (int)value;
    return 1;
}

int main(void)
{
    char first_line[128];
    char second_line[128];
    char extra_line[128];
    int first;
    int second;

    if (!read_line(first_line, sizeof first_line) ||
        !read_line(second_line, sizeof second_line) ||
        !parse_int_line(first_line, &first) ||
        !parse_int_line(second_line, &second)) {
        fputs("invalid input\n", stderr);
        return 1;
    }

    while (fgets(extra_line, sizeof extra_line, stdin) != NULL) {
        size_t i;
        for (i = 0U; extra_line[i] != '\0'; ++i) {
            if (isspace((unsigned char)extra_line[i]) == 0) {
                fputs("invalid input\n", stderr);
                return 1;
            }
        }
    }
    if (ferror(stdin) != 0) {
        fputs("input error\n", stderr);
        return 1;
    }

    printf("%lld\n", (long long)first + (long long)second);
    return 0;
}

#include <stddef.h>
#include <stdio.h>

int find_pair_sum(const int values[], size_t count, int target,
                  size_t *first_index, size_t *second_index)
{
    size_t i;
    size_t j;

    if (first_index == NULL || second_index == NULL ||
        (count != 0U && values == NULL)) {
        return 0;
    }

    for (i = 0U; i < count; ++i) {
        for (j = i + 1U; j < count; ++j) {
            if ((long long)values[i] + (long long)values[j] ==
                (long long)target) {
                *first_index = i;
                *second_index = j;
                return 1;
            }
        }
    }
    return 0;
}

int main(void)
{
    const int values[] = { 4, 7, 1, 9, 3 };
    const size_t count = sizeof values / sizeof values[0];
    size_t first;
    size_t second;

    if (find_pair_sum(values, count, 10, &first, &second)) {
        printf("%zu %zu\n", first, second);
    } else {
        puts("no pair");
    }
    return 0;
}
